      desc: 'Ведомые посланником Цинцюэ, вы прибываете в Комиссию по предсказаниям, которая отвечает за вычисления и управление информацией на Сяньчжоу.',
      steps: {
        enter: { text: 'Войдите в Комиссию по предсказаниям', ats: [['lf_d_arrive', 'lf_sanctum:с'], ['lf_d_gate_seen', 'lf_divination:в']], desc: 'Карнизы этого здания опираются друг на друга, как вздымающиеся горные вершины. Двери Комиссии закрыты и не собираются принимать гостей, и даже Цинцюэ не в силах с ними совладать.' },
        follow: { text: 'Следуйте за Цинцюэ к боковому входу в Комиссию по предсказаниям', desc: 'Цинцюэ знает аварийный вход. Сотрудники Комиссии называют его «воротами для бездельников».' },
        repair: { text: 'Откройте боковой вход с помощью подсказок Цинцюэ', at: 'lf_divination:С', desc: 'Механизм ворот заблокирован коррозией Стелларона. Вельт хочет взглянуть на пульт.' },
        meet: { text: 'Отправляйтесь с Цинцюэ на встречу с Фу Сюань', ats: [['lf_gate_win', 'lf_divination:б'], ['lf_t_mx', 'lf_divination:м'], ['lf_m_core', 'lf_matrix:ф']], desc: 'Хотя вы и гости, сейчас вы взламываете замки и двери, словно шайка воров. Самое время спросить Верховную провидицу о её планах.' },
        temporal: { text: 'Перезапустите временной терминал', at: 'lf_matrix:Т', desc: 'Ширмы телепортации ведут от ядра к островам с терминалами. Цинцюэ будет вас сопровождать.' },
        others: { text: 'Перезапустите пространственный и кармический терминалы', count: ['lf_term_s', 'lf_term_k'], ats: [['lf_term_s', 'lf_matrix:П'], ['lf_term_k', 'lf_matrix:Л']], desc: 'Порядок неважен. Перед пространственным терминалом стоит ауруматон-привратник.' },
        report: { text: 'Возвращайтесь в ядро Матрицы и доложите Фу Сюань', at: 'lf_matrix:Ф', desc: 'Все три терминала активированы. Всё готово для «допроса».' }
      }
