    lf_r_gongshu_end: [
      { recap: 'Легенда о хелиоби', text: 'Мастер Гуншу объясняет, почему бережёт печь: в ней заперты хелиоби, существа из чистой энергии, питавшиеся чувствами смертных. Он не знает, правда ли это, но пламя в печи и впрямь никогда не гасло.' },
      'gongshu|Спасибо за помощь. Об остальном позаботимся мы с моими бестолковыми учениками... На самый худой конец, у нас есть Облачные Рыцари.',
      '#q',
      { menu: [['«Почему вы так переживаете из-за этой печи?»', 'a'], ['«Вы знаете, что произошло в гроте Комиссии по алхимии?»', 'b']], exit: ['«Что ж, тогда прощаемся.»', 'x'] },
      '#a',
      'gongshu|Это всего лишь легенда... Хотя если учесть, что Древо амброзии ожило, она больше не кажется мне абсурдной...',
      'gongshu|В ней говорится, что давным-давно, когда Альянс Сяньчжоу дрейфовал в далёком космосе, он встретил множество невероятных жизненных форм.',
      'gongshu|Среди них были чудовища под названием «хелиоби». Они существовали исключительно в энергетической форме, однако питались чувствами и желаниями смертных созданий из плоти и крови. Иногда они умудрялись проникнуть в гроты Сяньчжоу, чтобы околдовывать людей и паразитировать на них.',
      'gongshu|Говорят, смертные, которыми овладевали хелиоби, постепенно теряли свободную волю, а потом впадали в буйство.',
      'gongshu|После длительной борьбы жители Сяньчжоу наконец-то смогли поймать и запереть хелиоби в некоем сосуде.',
      'gongshu|Этим сосудом и является Печь сотворения. Наши предки надеялись, что в печи эти твари постепенно лишатся всей своей энергии и сдохнут.',
      'gongshu|Я не знаю, есть ли в печи демоны - может быть, это всего лишь суеверие. Но я присматриваю за ней с того самого дня, как поступил в обучение к своему мастеру.',
      'gongshu|И пламя в ней и впрямь никогда не гасло...',
      { jump: 'q' },
      '#b',
      'gongshu|Всё случилось так быстро. Для нас с учениками это оказалось полной неожиданностью.',
      { choice: [['«Генерал считает, что в Комиссии по алхимии есть предатели.»', 'c'], ['«Говорят, что диверсию в Комиссии устроили Ученики Санктус Медикус.»', 'd']] },
      '#c',
      'gongshu|Меня это не удивляет. Алхимики из Комиссии когда-то были ближе к Древу, чем любые другие обитатели Лофу.',
      { jump: 'e' },
      '#d',
      'gongshu|Ученики Санктус Медикус? Знакомое название.',
      '#e',
      'gongshu|Говорят, когда Древо амброзии впервые появилось на Лофу Сяньчжоу, Комиссия по алхимии обрела невероятное влияние. С помощью силы Древа алхимики трансформировали смертные тела, манипулировали погодой и создавали никогда невиданных прежде тварей.',
      'gongshu|Они называли себя «святыми». К сожалению, никаких божественных сил у них не было. Когда Древо засохло, алхимики потеряли свой статус и вернулись к медицинским изысканиям и практикам.',
      { jump: 'q' },
      '#x',
      'gongshu|Жаль, что не смогу сопровождать вас дальше.',
      { if: 'lf_pill_given', jump: 'done' },
      { flag: 'lf_pill_given' },
      'gongshu|Ах, ненавижу быть в долгу. Возьмите вот это в награду за свои беспрестанные усилия.',
      { give: { items: { lf_pill: 1 } } },
      '#done',
      { end: true }
    ],
    lf_r_march: ['march|«Ботаническая катастрофа»? Это наверняка Древо амброзии...'],
